INSERT OR REPLACE INTO rules (id, rule, why, doc, added) VALUES (179, 'Every reported result states N, the number of variants tried to reach it, and is judged against the deflated bar c* = Z^-1(1 - 0.05/N) (10 tries 2.58, 20 tries 2.81, 40 tries 3.02), not 1.96. Forward paper records are the only evidence that needs no deflation.', 'multiple-testing: the expected best t-stat of N skill-less tries is ~3.6 at N=3,757 (Rossst, 23 Oct 2026); matches the Sept audit (doc 45/48) and the matched-control method', 118, '2026-10-23');
INSERT OR REPLACE INTO rules (id, rule, why, doc, added) VALUES (180, 'Live sizing is derived from the loss cap, not the other way round: the daily loss cap is 5-10% of the account, the per-trade stop risk at most 2%, and the stake per point follows from those. The demo runs 1 GBP/pt with a 200-pt cap only because it is a rehearsal.', 'doc 119: 200 pts at 1 GBP/pt is 40% of a 500 GBP float', 119, '2026-10-23');
INSERT OR REPLACE INTO findings (doc, title, date, verdict, superseded_by, summary) VALUES (119, 'Ignition refinements tested; feed calibration', '2026-10-23', 'threshold calibrated; v1.1 stands; target irrelevant', NULL, 'IG ticks 1.71x Dukascopy so delta share runs smaller in the tails (ratio 0.878 at the 90th pct): demo threshold 0.0439 until 500 IG bars then percentile-matched (0.05 = top 9.1% of Dukascopy bars). Both 22 Oct paper winners (14:25, 16:30 UTC) read -0.049 on IG and were missed. Target 9 ATR never prints; 4 ATR +2%/yr, none identical; lunch skip beats a 2x ignition bar in lunch (+20.4 vs +17.5/trade) in both halves. v3.1 (hold through regime switch) test running.');
ALTER TABLE pb6_equity ADD COLUMN equity_v31 REAL;
ALTER TABLE pb6_equity ADD COLUMN open_v31 INTEGER;
ALTER TABLE pb6_equity ADD COLUMN closed_v31 INTEGER;
INSERT OR REPLACE INTO findings (doc, title, date, verdict, superseded_by, summary) VALUES (120, 'Range v3.1: hold through the regime switch', '2026-10-23', 'registered as a parallel ledger inside the range book from 24 Oct', NULL, 'Five years, 27 coins, v3 costs: v3 +0.179%/ep (72% win, t 46) vs v3.1 +0.247%/ep (79% win, t 60); better on 27/27 coins, both halves of every coin, all six years (2021 +0.355 vs +0.219 ... 2026 +0.246 vs +0.181). One variant tried. Cost: stops 618 -> 1,719 and breaks 4,301 -> 6,949 of ~86k episodes - the drawdown is the paper-month question.');
INSERT OR REPLACE INTO rules (id, rule, why, doc, added) VALUES (181, 'Range v3.1 (hold through the regime switch) runs as a parallel ledger beside v3 - never instead - until it has a forward record; the same change is a candidate for ETF v3 and Range v3-IDX only after v3.1 shows forward.', 'doc 120', 120, '2026-10-23');
